  ('max_allied_coverage_blocks','8','integer'::value_type_enum,NULL),
  ('max_notification_delivery_attempts','12','integer'::value_type_enum,'Dispatch attempts before a notification is dead-lettered. With the capped exponential backoff below this is roughly 7 hours of retrying.'),
  ('min_float_chunk_blocks','1','integer'::value_type_enum,NULL),
  ('no_ack_trigger_offset_minutes','5','integer'::value_type_enum,NULL),
  ('notification_retry_backoff_cap_minutes','60','integer'::value_type_enum,'Ceiling on the exponential retry backoff between dispatch attempts.'),
  ('open_shift_permanent_horizon_weeks','26','integer'::value_type_enum,'How far ahead the PERMANENT-OPENINGS feed looks. Deliberately longer than the weekly horizon so a permanently-dropped slot stays pickable as a whole recurrence for the rest of the semester.'),
  ('open_shift_weekly_horizon_weeks','6','integer'::value_type_enum,'How far ahead the WEEKLY open-shifts feed looks. The mobile calendar navigates last-week…+4, so 6 weeks covers it with headroom. Bounds worker_open_shifts.'),
